// AlphaAI insider (SEC Form 4) -> Discord rich embeds.
// One message per run: header + up to 10 cards, each linking to the filing's
// page on alphai.io. Colours by detected Buy/Sell, shows direct/indirect holding
// form. Dedupes by uid across runs; overflow posts next run. One POST per run.

// ▼ tune this: minimum relevance score to alert on (endpoint already floors at 4).
// The insider score scales with transaction value — 6 skips the tiny trades.
const MIN_SCORE = 6;

function slugify(text) {
  return (text || '').toLowerCase()
    .replace(/[^\w\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').trim();
}
function dateForUrl(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) { return ''; }
  return String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0');
}
function trunc(s, n) { s = (s == null ? '' : String(s)); return s.length > n ? s.slice(0, n - 1) + '…' : s; }

const SITE = 'https://alphai.io';
const GREEN = 3066993, RED = 15158332, GREY = 9807270;

const incoming = $input.all();
let articles = [];
for (const it of incoming) {
  const j = it.json;
  if (Array.isArray(j)) { articles = articles.concat(j); }
  else if (j && Array.isArray(j.results)) { articles = articles.concat(j.results); }
  else if (j) { articles.push(j); }
}

const store = $getWorkflowStaticData('global');
store.postedUids = store.postedUids || [];
const seen = new Set(store.postedUids);

const embeds = [];
const postedUids = [];
let budget = 0;

for (const a of articles) {
  if (embeds.length >= 10) { break; }
  const enr = (a && a.enrichment) || {};
  const org = (a && a.original) || {};
  const uid = org.uid;
  const score = enr.relevance_score || 0;
  const tickers = enr.tickers || [];
  if (!uid || seen.has(uid)) { continue; }
  if (score < MIN_SCORE || tickers.length === 0) { continue; }

  // Detect Buy/Sell from the filing's templated text (best-effort).
  const hay = ((org.title || '') + ' ' + (org.summary || '')).toLowerCase();
  let direction = '—', color = GREY;
  if (/\b(bought|buy|purchas|acqui)/.test(hay)) { direction = 'Buy'; color = GREEN; }
  else if (/\b(sold|sell|sale|dispos)/.test(hay)) { direction = 'Sell'; color = RED; }

  const url = `${SITE}/news/article/${dateForUrl(org.time_published)}/${uid}/${slugify(org.title)}`;

  const fields = [];
  fields.push({ name: 'Direction', value: direction, inline: true });
  if (org.ownership_form) { fields.push({ name: 'Holding', value: trunc(org.ownership_form, 40), inline: true }); }
  fields.push({ name: 'Score', value: String(score) + '/10', inline: true });

  const embed = {
    title: trunc(`${tickers.join(', ')} — ${org.title || 'Insider filing'}`, 250),
    url,
    description: trunc(org.summary || '', 320),
    color,
    fields,
    footer: { text: trunc(`insider · ${org.source || org.source_domain || 'SEC EDGAR'} · via AlphaAI`, 120) },
  };
  if (org.time_published) { embed.timestamp = org.time_published; }

  const size = JSON.stringify(embed).length;
  if (budget + size > 5200 && embeds.length > 0) { break; }
  budget += size;

  embeds.push(embed);
  postedUids.push(uid);
  seen.add(uid);
}

if (embeds.length === 0) { return []; }

for (const uid of postedUids) { store.postedUids.push(uid); }
if (store.postedUids.length > 500) { store.postedUids = store.postedUids.slice(-500); }

const n = embeds.length;
const content = `🕵️ **AlphaAI — ${n} new insider ${n === 1 ? 'filing' : 'filings'}**`;

return [{ json: { payload: { content, embeds } } }];
